#include <limits>
using namespace std;

int main() {
    long long n;
    cin >> n;

    vector<long long> a(n);
    for (long long &x : a) cin >> x;

    long long bil = numeric_limits<long long>::max();

    for (long long j = 1; j <= n; ++j) {
        long long bill = 0;
        for (long long i = 0; i < n; ++i) {
            bill += llabs(j - i - 1) + i + llabs(j - 1) * a[i];
        }
        if (bill < bil) bil = bill;
    }

    cout << 2 * bil << '\n';
    return 0;
}

